local k={70,70,41,254,132,250,191,39,11,232,168,181,117,163,172,28,96,223,247,201,204,83,247,65,240,225,27,96,92,37,53,215}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
